/**
 * Machine a etats minimale (un seul etat actif a la fois).
 *
 *   const fsm = new StateMachine(ennemi, {
 *       PATROL: {
 *           enter(owner, from)   { ... },            // optionnel : a l'entree dans l'etat
 *           update(owner, dt)    { ... },            // optionnel : a chaque update(dt)
 *           exit(owner, to)      { ... },            // optionnel : a la sortie
 *           transitions: [                           // optionnel : evaluees apres update, dans l'ordre
 *               { to: 'CHASE', when: (owner) => owner.seesPlayer() }   // sans `when` : toujours
 *           ]
 *       },
 *       CHASE: { ... }
 *   }, 'PATROL');
 *
 *   fsm.update(dt);          // a appeler a chaque frame
 *   fsm.change('IDLE');      // transition forcee (ignoree si deja dans cet etat)
 *   fsm.is('CHASE');  fsm.current;  fsm.previous;  fsm.time (secondes passees dans l'etat)
 *
 * Volontairement sans hierarchie ni etats paralleles : une table d'etats avec fonctions, comme on
 * l'ecrirait en C (tableau + pointeurs de fonction). Les noms d'etats sont des chaines : lisibles dans le debugger.
 */
export class StateMachine {
    /**
     * @param pOwner   objet passe en premier argument a toutes les fonctions d'etat
     * @param pStates  { NOM: { enter, update, exit, transitions } }
     * @param pInitial nom de l'etat de depart (son enter() est appele tout de suite)
     */
    constructor(pOwner, pStates, pInitial) {
        this.owner = pOwner;
        this.states = pStates;
        this.current = null;
        this.previous = null;
        this.time = 0;
        if (pInitial !== undefined) this.change(pInitial);
    }

    is(pName) { return this.current === pName; }

    change(pName) {
        if (pName === this.current) return false;
        const next = this.states[pName];
        if (!next) throw new Error("StateMachine : etat inconnu '" + pName + "'");
        const prev = this.states[this.current];
        if (prev && prev.exit) prev.exit(this.owner, pName, this);
        this.previous = this.current;
        this.current = pName;
        this.time = 0;
        if (next.enter) next.enter(this.owner, this.previous, this);
        return true;
    }

    update(pDt = 0) {
        const state = this.states[this.current];
        if (!state) return;
        this.time += pDt;
        if (state.update) state.update(this.owner, pDt, this);
        // une transition peut avoir ete declenchee par update() lui-meme (change) : on n'evalue que pour l'etat d'origine
        if (state.transitions && this.states[this.current] === state) {
            for (const t of state.transitions) {
                if (!t.when || t.when(this.owner, this)) {
                    this.change(t.to);
                    break;
                }
            }
        }
    }
}
