/**
 * Pas de temps fixe ("fixed timestep").
 *
 * Probleme : si la physique avance de dt a chaque frame, le jeu se comporte differemment a 30, 60
 * ou 144 fps (hauteur de saut, vitesse, collisions qui laissent passer a travers le sol...).
 * Solution : on accumule le temps reel et on simule par pas CONSTANTS (1/60 s par defaut). Le
 * resultat est identique quelle que soit la frequence d'affichage.
 *
 *   const fixed = new FixedStep();
 *   fixed.run(dtReel, (dt) => monde.step(dt));   // dt vaut toujours 1/60
 *
 * pMaxSteps evite la "spirale de la mort" apres un gros lag (onglet en arriere-plan...) : au-dela,
 * on abandonne le temps en retard au lieu de rattraper pendant des secondes.
 */
export class FixedStep {
    constructor(pStep = 1 / 60, pMaxSteps = 5) {
        this.step = pStep;
        this.maxSteps = pMaxSteps;
        this.accumulator = 0;
    }

    /** @returns le nombre de pas simules */
    run(pDt, pFn) {
        this.accumulator += pDt;
        let n = 0;
        while (this.accumulator >= this.step && n < this.maxSteps) {
            pFn(this.step);
            this.accumulator -= this.step;
            n++;
        }
        if (n === this.maxSteps) this.accumulator = 0; // trop de retard : on laisse tomber
        return n;
    }

    /** fraction (0..1) du prochain pas deja ecoulee : pour interpoler l'affichage si besoin */
    get alpha() { return this.accumulator / this.step; }

    reset() { this.accumulator = 0; }
}
