export class MonstreStats {
    constructor(pMonstreType, pLevel, pXP, pMaxHP, pAttMin, pAttMax, pAttType, pLoot) {
        this._type = pMonstreType;
        this._level = pLevel;
        this._xp = pXP;

        this.maxHp = pMaxHP;
        this.dmg = 0;

        this.attMin = pAttMin;
        this.attMax = pAttMax;
        
        this.attType = pAttType;
        
        this.resistance = [];
        this.immunities = [];

        this.loot = Math.random() <= pLoot;
    }

    get hp() {
        return Math.max(0, this.maxHp - this.dmg);
    }
}

MonstreStats.TYPE_SQUELETTE = 1;

MonstreStats.ATT_PHYSIQUE = 1;