import { Command } from '../../../core/commandPattern/Command.js';
import { BT } from '../../../engine/BT.js';

export class CommandAttack extends Command {
    constructor(pReceiver, pAttMin, pAttMax) {
        super(pReceiver);
        this.att = BT.getRandomInt(pAttMin, pAttMax); 
    }

    execute() {        
        return this.att;
    }

    undo() {
        return -1 * this.att;
    }
}