/**
 * Generateur pseudo-aleatoire a graine (mulberry32) : meme graine = meme suite de nombres, sur tous les
 * navigateurs. Sert a generer un labyrinthe ou a rejouer un bug ; Math.random() ne le permet pas.
 *
 *   const rng = new Random(12345);
 *   rng.next();          // flottant dans [0, 1[
 *   rng.int(1, 6);       // entier dans [1, 6]
 *   rng.pick(tableau);   // un element au hasard
 *   rng.chance(0.25);    // vrai une fois sur quatre
 *   rng.seed;            // la graine d'origine (a afficher pour pouvoir rejouer)
 */
export class Random {
    constructor(pSeed = Date.now()) {
        this.seed = pSeed >>> 0;
        this._state = this.seed;
    }

    next() {
        let t = (this._state += 0x6D2B79F5) >>> 0;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    }

    int(pMin, pMax) { return pMin + Math.floor(this.next() * (pMax - pMin + 1)); }
    pick(pArray) { return pArray[Math.floor(this.next() * pArray.length)]; }
    chance(pProbability) { return this.next() < pProbability; }
}
