import { Datas } from '../../engine/Datas.js';
import { Random } from '../../core/Random.js';
import { Enemy } from './entities/Enemy.js';
import { PlayerStats } from './entities/PlayerStats.js';

export class DatasManager {
    constructor() { }

    static init() {
        this._playerStats = new PlayerStats("Yop", "Aventurier");
        this._encounters = []; // combats en attente (rempli au contact d'un ennemi, ou par la touche P)
        // ennemis poses dans le labyrinthe (cases de la grille). Ils survivent aux changements d'ecran :
        // Game se reconstruit apres chaque combat. engaged = en train d'etre combattu (retire au retour).
        this._enemies = [
            new Enemy(Datas.STALFOS, 9, 3),
            new Enemy(Datas.STALFOS, 4, 10),
            new Enemy(Datas.STALFOS, 10, 8)
        ];
        // hasard du jeu (comportement des ennemis) : ?seed=123 dans l'URL pour rejouer exactement la meme partie
        const seed = parseInt(new URLSearchParams(location.search).get('seed'));
        this._rng = new Random(Number.isFinite(seed) ? seed : undefined);
        console.info("seed du hasard :", this._rng.seed);
        this._encounterStats = [];
        this._lastPlayerPosition = null;
        this._lastPlayerDirection = null;
    }

    static get playerStats() {
        return this._playerStats;
    }

    // --
    static get encounters() {
        return this._encounters;
    }

    static get enemies() {
        return this._enemies;
    }

    /** au retour d'un combat : l'ennemi qui vient d'etre affronte disparait du labyrinthe */
    static removeEngagedEnemies() {
        this._enemies = this._enemies.filter((e) => !e.engaged);
    }

    static get rng() {
        return this._rng;
    }

    static get encounterStats() {
        return this._encounterStats;
    }

    static set encounterStats(pValue) {
        this._encounterStats = pValue;
    }

    // --
    static get lastPlayerPosition() {
        return this._lastPlayerPosition;
    }
    static set lastPlayerPosition(pValue) {
        this._lastPlayerPosition = pValue;
    }

    // --
    static get lastPlayerDirection() {
        return this._lastPlayerDirection;
    }
    static set lastPlayerDirection(pValue) {
        this._lastPlayerDirection = pValue;
    }
}

DatasManager.ENCOUNTER_FIGHT = "DatasManager::encounter_fight";
DatasManager.ENCOUNTER_PNJ = "DatasManager::encounter_pnj";